function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError("intervals debe ser un array");
  }

  const sorted = intervals.map((interval) => {
    if (
      !Array.isArray(interval) ||
      interval.length !== 2 ||
      !Number.isFinite(interval[0]) ||
      !Number.isFinite(interval[1]) ||
      interval[0] > interval[1]
    ) {
      throw new TypeError("Cada intervalo debe ser un par de números finitos con inicio <= fin");
    }

    return [interval[0], interval[1]];
  });

  sorted.sort((a, b) => a[0] - b[0]);

  const merged = [];

  for (const interval of sorted) {
    const last = merged[merged.length - 1];

    if (!last || interval[0] > last[1]) {
      merged.push(interval);
    } else {
      last[1] = Math.max(last[1], interval[1]);
    }
  }

  return merged;
}

module.exports = mergeIntervals;
