export class CrystalScene {
  constructor(container, options = {}) {
    if (!container) {
      throw new Error('CrystalScene necesita un elemento contenedor.');
    }

    this.container = container;
    this.disposed = false;
    this.backgroundColor = options.backgroundColor ?? 0x080b18;

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(this.backgroundColor);
    this.scene.fog = new THREE.Fog(this.backgroundColor, 7, 18);

    this.camera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);
    this.camera.position.set(0, 0, 5.8);

    this.renderer = new THREE.WebGLRenderer({
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
    });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.15;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.domElement.style.display = 'block';
    this.renderer.domElement.style.width = '100%';
    this.renderer.domElement.style.height = '100%';
    this.container.appendChild(this.renderer.domElement);

    this.crystal = new THREE.Group();
    this.scene.add(this.crystal);

    this.crystalGeometry = this.createCrystalGeometry();
    this.crystalMaterial = new THREE.MeshPhysicalMaterial({
      vertexColors: true,
      flatShading: true,
      roughness: 0.24,
      metalness: 0.12,
      clearcoat: 1,
      clearcoatRoughness: 0.18,
      emissive: 0x11172d,
    });

    const mesh = new THREE.Mesh(this.crystalGeometry, this.crystalMaterial);
    this.crystal.add(mesh);

    this.addLighting();

    this.clock = new THREE.Clock();
    this.resize = this.resize.bind(this);
    this.renderer.setAnimationLoop(() => this.animate());

    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(this.resize);
      this.resizeObserver.observe(this.container);
    } else {
      window.addEventListener('resize', this.resize);
    }

    this.resize();
  }

  createCrystalGeometry() {
    const sides = 8;
    const phase = Math.PI / 8;
    const levels = [
      { y: -0.78, radius: 0.48 },
      { y: -0.16, radius: 0.76 },
      { y: 0.52, radius: 0.57 },
    ];

    const rings = levels.map((level, ringIndex) =>
      Array.from({ length: sides }, (_, i) => {
        const angle = (i / sides) * Math.PI * 2 + phase;
        const variation = 1 + 0.055 * Math.sin(i * 2.31 + ringIndex * 1.7);
        const radius = level.radius * variation;

        return new THREE.Vector3(
          Math.cos(angle) * radius,
          level.y,
          Math.sin(angle) * radius,
        );
      }),
    );

    const triangles = [];
    const addTriangle = (a, b, c) => triangles.push(a, b, c);

    // Facetas laterales trianguladas.
    for (let level = 0; level < rings.length - 1; level++) {
      const lower = rings[level];
      const upper = rings[level + 1];

      for (let i = 0; i < sides; i++) {
        const next = (i + 1) % sides;
        addTriangle(lower[i], upper[i], upper[next]);
        addTriangle(lower[i], upper[next], lower[next]);
      }
    }

    const top = new THREE.Vector3(0.03, 1.32, 0.01);
    const bottom = new THREE.Vector3(-0.02, -1.34, 0);

    for (let i = 0; i < sides; i++) {
      const next = (i + 1) % sides;
      addTriangle(rings[rings.length - 1][i], top, rings[rings.length - 1][next]);
      addTriangle(bottom, rings[0][i], rings[0][next]);
    }

    const positions = [];
    const colors = [];
    const faceColor = new THREE.Color();

    for (let face = 0; face < triangles.length / 3; face++) {
      const hue = 0.59 + 0.075 * Math.sin(face * 2.399);
      const lightness = 0.42 + 0.12 * Math.sin(face * 1.731 + 0.8);
      faceColor.setHSL(hue, 0.78, lightness);

      for (let vertex = 0; vertex < 3; vertex++) {
        const point = triangles[face * 3 + vertex];
        positions.push(point.x, point.y, point.z);
        colors.push(faceColor.r, faceColor.g, faceColor.b);
      }
    }

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geometry.computeVertexNormals();
    return geometry;
  }

  addLighting() {
    this.scene.add(new THREE.HemisphereLight(0xcbdcff, 0x171329, 1.7));

    const key = new THREE.DirectionalLight(0xffffff, 3.2);
    key.position.set(3, 4, 5);
    this.scene.add(key);

    const blueFill = new THREE.PointLight(0x526dff, 20, 12);
    blueFill.position.set(-3, 0.5, 2);
    this.scene.add(blueFill);

    const rim = new THREE.PointLight(0x7de7ff, 15, 10);
    rim.position.set(1, -2, -3);
    this.scene.add(rim);
  }

  resize() {
    if (this.disposed) return;

    const width = this.container.clientWidth || window.innerWidth || 1;
    const height = this.container.clientHeight || window.innerHeight || 1;

    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    this.renderer.setSize(width, height, false);
  }

  animate() {
    if (this.disposed) return;

    const time = this.clock.getElapsedTime();
    this.crystal.rotation.y = time * 0.42;
    this.crystal.rotation.x = Math.sin(time * 0.35) * 0.13;
    this.crystal.position.y = Math.sin(time * 1.15) * 0.14;

    this.renderer.render(this.scene, this.camera);
  }

  dispose() {
    if (this.disposed) return;
    this.disposed = true;

    this.renderer.setAnimationLoop(null);
    this.resizeObserver?.disconnect();
    window.removeEventListener('resize', this.resize);

    this.crystalGeometry.dispose();
    this.crystalMaterial.dispose();
    this.renderer.dispose();

    if (this.renderer.domElement.parentNode === this.container) {
      this.container.removeChild(this.renderer.domElement);
    }
  }
}

export default CrystalScene;
