function mergeIntervals(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('Input must be an array');
  }

  // Validate and copy intervals
  const copied = intervals.map((pair, idx) => {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError(`Interval at index ${idx} must be an array of two elements`);
    }
    const [start, end] = pair;
    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      throw new TypeError(`Interval at index ${idx} must contain finite numbers`);
    }
    if (start > end) {
      throw new TypeError(`Interval at index ${idx} has start > end`);
    }
    return [start, end];
  });

  // Sort by start
  const sorted = copied.sort((a, b) => a[0] - b[0]);

  const merged = [];
  for (const [start, end] of sorted) {
    if (merged.length === 0) {
      merged.push([start, end]);
      continue;
    }
    const last = merged[merged.length - 1];
    // Overlap or contiguous (touching)
    if (start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }

  return merged;
}

module.exports = mergeIntervals;
