/**
 * Calcula el tiempo de espera antes de reintentar una operación.
 *
 * Utiliza un backoff exponencial con jitter para evitar colisiones.
 * El retraso crece como `baseMs * 2^attempt` hasta un máximo de `maxMs`.
 * Se añade un factor aleatorio entre 0.8 y 1.2 (jitter) y se redondea al entero más cercano.
 *
 * @param {number} attempt - Número de intento actual (base 0).
 * @param {number} [baseMs=200] - Tiempo base en milisegundos para el primer intento.
 * @param {number} [maxMs=5000] - Límite superior del retraso en milisegundos.
 * @returns {number} Retraso calculado en milisegundos, con jitter aplicado.
 */
export function retryDelay(attempt, baseMs = 200, maxMs = 5000) {
  const exponential = Math.min(maxMs, baseMs * 2 ** attempt);
  return Math.round(exponential * (0.8 + Math.random() * 0.4));
}
