import * as THREE from 'https://cdn.jsdelivr.net/npm/three@latest/build/three.module.js';

/**
 * Crea una escena Three.js con un cristal low‑poly flotante.
 * @param {HTMLCanvasElement} canvas – Canvas donde se renderizará la escena.
 * @returns {{ dispose: () => void }} Objeto con método de limpieza.
 */
export function createCrystalScene(canvas) {
  // ---------- Renderer ----------
  const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(canvas.clientWidth, canvas.clientHeight);
  renderer.outputEncoding = THREE.sRGBEncoding;

  // ---------- Scene ----------
  const scene = new THREE.Scene();
  scene.fog = new THREE.Fog(0x0a0a0a, 1, 12); // niebla suave

  // ---------- Camera ----------
  const camera = new THREE.PerspectiveCamera(45, canvas.clientWidth / canvas.clientHeight, 0.1, 100);
  camera.position.set(0, 0, 5);

  // ---------- Lights ----------
  const ambient = new THREE.AmbientLight(0xffffff, 0.6);
  scene.add(ambient);

  const dirLight = new THREE.DirectionalLight(0xffffff, 1);
  dirLight.position.set(3, 5, 4);
  scene.add(dirLight);

  const rimLight = new THREE.DirectionalLight(0x88ccff, 0.5);
  rimLight.position.set(-3, -2, -3);
  scene.add(rimLight);

  // ---------- Crystal Geometry (low‑poly) ----------
  const baseGeo = new THREE.IcosahedronGeometry(1, 0); // 20 caras, muy low‑poly
  // Pequeño desplazamiento aleatorio para aspecto "cristalino"
  const posAttr = baseGeo.getAttribute('position');
  for (let i = 0; i < posAttr.count; i++) {
    const v = new THREE.Vector3().fromBufferAttribute(posAttr, i);
    v.addScaledVector(v.clone().normalize(), (Math.random() - 0.5) * 0.2);
    posAttr.setXYZ(i, v.x, v.y, v.z);
  }
  baseGeo.computeVertexNormals();

  // ---------- Crystal Material ----------
  const material = new THREE.MeshStandardMaterial({
    color: 0x66ccff,
    metalness: 0.2,
    roughness: 0.1,
    transmission: 0.9,
    thickness: 1.5,
    envMapIntensity: 1.2,
    transparent: true,
    opacity: 0.85,
    flatShading: true,
  });

  const crystal = new THREE.Mesh(baseGeo, material);
  scene.add(crystal);

  // ---------- Animation ----------
  let rafId;
  const animate = () => {
    rafId = requestAnimationFrame(animate);
    crystal.rotation.x += 0.003;
    crystal.rotation.y += 0.005;
    renderer.render(scene, camera);
  };
  animate();

  // ---------- Responsive Resize ----------
  const onResize = () => {
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
  };
  window.addEventListener('resize', onResize);

  // ---------- Dispose ----------
  function dispose() {
    cancelAnimationFrame(rafId);
    window.removeEventListener('resize', onResize);

    // Geometrías / Materiales
    baseGeo.dispose();
    material.dispose();

    // Renderer
    renderer.dispose();
    renderer.forceContextLoss();
    const gl = renderer.getContext();
    if (gl) gl.getExtension('WEBGL_lose_context')?.loseContext();

    // Limpiar referencias
    scene.clear();
  }

  return { dispose };
}
